// Get all items from previous node
const items = $input.all();

// Extract orders from each item
let orders = [];
for (const item of items) {
  if (Array.isArray(item.json)) {
    orders = orders.concat(item.json);
  } else {
    orders.push(item.json);
  }
}

// If no orders found, return zero values
if (orders.length === 0) {
  const today = new Date().toLocaleDateString('en-US', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });

  return [{
    json: {
      Date: today,
      TotalOrders: 0,
      TotalSales: "0.00",
      TotalTax: "0.00",
      TotalItems: 0,
      AverageOrder: "0.00",
      BestSeller: "N/A",
      BestSellerQty: 0,
      NewCustomers: 0,
      ReturningCustomers: 0,
      TotalRefunds: 0,
      InvoiceLinks: "No orders today",
      NoSales: true
    }
  }];
}

// Initialize counters
let totalSales = 0;
let totalTax = 0;
let totalItems = 0;
let orderCount = 0;
let totalRefunds = 0;

// Best Selling Product tracking
const productSales = {};

// New vs Returning customers
let newCustomers = 0;
let returningCustomers = 0;

// Invoice links collection
let invoiceLinks = [];

// Loop through each order
for (const order of orders) {
  totalSales += parseFloat(order.total || 0);
  totalTax += parseFloat(order.total_tax || 0);
  orderCount++;

  // Count items in each order
  if (order.line_items && Array.isArray(order.line_items)) {
    for (const item of order.line_items) {
      totalItems += item.quantity || 0;

      // Track best selling product
      const name = item.name || "Unknown";
      productSales[name] = (productSales[name] || 0) + (item.quantity || 0);
    }
  }

  // Track new vs returning customers
  if (order.customer_id === 0 || !order.customer_id) {
    newCustomers++;
  } else {
    returningCustomers++;
  }

  // Track refunds
  if (order.status === 'refunded' || order.status === 'refund') {
    totalRefunds += parseFloat(order.total || 0);
  }

  // Collect invoice links
  const orderId = order.id;
  const orderLink = `https://dev-faz-store63.pantheonsite.io/wp-admin/post.php?post=${orderId}&action=edit`;
  invoiceLinks.push({
    id: orderId,
    link: orderLink,
    total: order.total,
    status: order.status
  });
}

// Calculate average
const averageOrder = orderCount > 0 ? (totalSales / orderCount).toFixed(2) : "0.00";

// Get best selling product
const bestSeller = Object.entries(productSales)
  .sort((a, b) => b[1] - a[1])[0] || ["N/A", 0];

// Get today's date
const today = new Date().toLocaleDateString('en-US', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

// Format invoice links for email
const invoiceLinksHtml = invoiceLinks.map(inv => 
  `Order #${inv.id} - ${inv.status} - BDT ${inv.total} - ${inv.link}`
).join('\n');

// Return as array (required for Google Sheets)
return [{
  json: {
    Date: today,
    TotalOrders: orderCount,
    TotalSales: totalSales.toFixed(2),
    TotalTax: totalTax.toFixed(2),
    TotalItems: totalItems,
    AverageOrder: averageOrder,
    BestSeller: bestSeller[0],
    BestSellerQty: bestSeller[1],
    NewCustomers: newCustomers,
    ReturningCustomers: returningCustomers,
    TotalRefunds: totalRefunds.toFixed(2),
    InvoiceLinks: invoiceLinksHtml,
    NoSales: false
  }
}];

